// 合并为单列表；精选词优先（去重），cat 用于分类筛选
const N2_VOCAB = [];
const _seen = new Set();
N2_VOCAB_CATS.forEach(c => { c.items.forEach(v => { const key = v.k + "|" + v.r; if (_seen.has(key)) return; _seen.add(key); v.cat = "精选·" + c.name; N2_VOCAB.push(v); }); });
N2_VOCAB_EXTRA_CATS.forEach(c => { c.items.forEach(v => { const key = v.k + "|" + v.r; if (_seen.has(key)) return; _seen.add(key); v.cat = c.name; N2_VOCAB.push(v); }); });